import json
from pathlib import Path

# Український алфавіт для сортування "за абеткою"; решта символів — після нього за кодом
АБЕТКА = "абвгґдеєжзиіїйклмнопрстуфхцчшщьюя"


def ключ_абетки(рядок):
    return [АБЕТКА.index(c) if c in АБЕТКА else 100 + ord(c) for c in рядок.lower()]


def формат(значення):
    if isinstance(значення, str):
        return значення
    return json.dumps(значення, ensure_ascii=False)


def main():
    with open(Path("дані") / "конфіги.json", encoding="utf-8") as f:
        конфіги = json.load(f)

    for ім_я in sorted(конфіги, key=ключ_абетки):
        # Збираємо ланцюжок предків; якщо він повертається до вже побаченого вузла — цикл
        ланцюжок = []
        поточний = ім_я
        цикл = False
        while поточний is not None:
            if поточний in ланцюжок:
                цикл = True
                break
            if поточний not in конфіги:
                break
            ланцюжок.append(поточний)
            поточний = конфіги[поточний].get("успадковує")

        if цикл:
            print(f"{ім_я}: цикл")
            continue

        # Від кореня до самого конфігу: значення власні перекривають предкові
        підсумок = {}
        for вузол in reversed(ланцюжок):
            підсумок.update(конфіги[вузол].get("значення", {}))

        пари = [f"{k}={формат(підсумок[k])}" for k in sorted(підсумок, key=ключ_абетки)]
        if пари:
            print(f"{ім_я}: {', '.join(пари)}")
        else:
            print(f"{ім_я}:")


if __name__ == "__main__":
    main()

